  info:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><circle cx="12" cy="12" r="9"/><path d="M12 8h.01M11 12h1v5h1"/></svg>',
  mail:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M4 6h16v12H4z"/><path d="m4 7 8 6 8-6"/></svg>',
  tick:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="3"><path d="m5 12 5 5 9-10"/></svg>'
};

/* ================= Helpers ================= */
var uidN = 1000;
function uid(p){ return (p||"id") + (++uidN); }
function $(s,r){ return (r||document).querySelector(s); }
function $$(s,r){ return Array.prototype.slice.call((r||document).querySelectorAll(s)); }
function esc(s){ return String(s==null?"":s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;"); }
function initials(n){ return String(n||"?").split(/\s+/).filter(Boolean).slice(0,2).map(function(w){return w[0];}).join("").toUpperCase(); }
var HUES = ["#2A74C6","#2C7A57","#8A4B9C","#A2582B","#2E6E7E","#7A5B1E","#5A6478","#9C3D54"];
function hue(s){ var h=0; s=String(s||""); for(var i=0;i<s.length;i++) h=(h*31+s.charCodeAt(i))>>>0; return HUES[h%HUES.length]; }
function avatar(name){ return '<span class="avatar" style="background:'+hue(name)+'">'+esc(initials(name))+'</span>'; }
function sw(on,action,id,label){ return '<button type="button" class="switch" role="switch" aria-checked="'+(!!on)+'" aria-label="'+esc(label)+'" data-action="'+action+'" data-id="'+id+'"></button>'; }
function rowActions(kind,id,name){
  return '<button class="icon-btn" data-action="edit-'+kind+'" data-id="'+id+'" aria-label="Edit '+esc(name)+'" title="Edit">'+I.edit+'</button>'+
         '<button class="icon-btn del" data-action="del-'+kind+'" data-id="'+id+'" aria-label="Delete '+esc(name)+'" title="Delete">'+I.del+'</button>';
}
function searchBox(key,ph){ return '<label class="search"><span class="sr">Search</span>'+I.search+'<input type="search" data-search="'+key+'" placeholder="'+esc(ph)+'" value="'+esc(ui.q[key]||"")+'"></label>'; }
function match(q){ q=(q||"").trim().toLowerCase(); return function(){ var s=Array.prototype.join.call(arguments," ").toLowerCase(); return !q||s.indexOf(q)>-1; }; }
function byId(list,id){ for(var i=0;i<list.length;i++) if(list[i].id===id) return list[i]; return null; }
function emailOk(e){ return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e); }
function snapshot(){ return JSON.stringify(S); }
function plural(n,word){ return n+" "+word+(n===1?"":"s"); }

/* ================= Toast ================= */
function toast(msg,undoSnap){
  var t=document.createElement("div"); t.className="toast";
  t.innerHTML='<span>'+esc(msg)+'</span>'+(undoSnap?'<button type="button">Undo</button>':'');
  $("#toasts").appendChild(t);
  var timer=setTimeout(function(){ t.remove(); }, undoSnap?6000:3200);
  if(undoSnap) t.querySelector("button").onclick=function(){ S=JSON.parse(undoSnap); clearTimeout(timer); t.remove(); render(); toast("Restored"); };
}

/* ================= Confirm ================= */
var lastFocus=null, confirmCb=null;
function confirmDel(title,text,cb){
  lastFocus=document.activeElement;
  $("#c-title").textContent=title; $("#c-text").textContent=text; confirmCb=cb;
  $("#scrim").classList.add("open"); $("#confirm").classList.add("open"); $("#c-cancel").focus();
}
function closeConfirm(){
  $("#confirm").classList.remove("open");
  if(!D) $("#scrim").classList.remove("open");
  confirmCb=null; if(lastFocus) lastFocus.focus();
}
$("#c-cancel").onclick=closeConfirm;
$("#c-ok").onclick=function(){ var cb=confirmCb; closeConfirm(); if(cb) cb(); };

/* ================= Dialog ================= */
var D=null;
function openDialog(cfg){
  D=cfg; D.chips=cfg.chips||{}; lastFocus=document.activeElement;
  $("#d-title").textContent=cfg.title;
  $("#d-sub").textContent=cfg.sub||""; $("#d-sub").hidden=!cfg.sub;
  $("#d-save").textContent=cfg.saveLabel||"Save changes";
  $("#d-body").innerHTML=cfg.body; $("#d-body").scrollTop=0;
  $("#scrim").classList.add("open"); $("#dialog").classList.add("open");
  if(cfg.setup) cfg.setup($("#d-body"));
  setTimeout(function(){ var f=$("#d-body input:not([type=checkbox]):not([type=file]),#d-body textarea,#d-body select"); if(f) f.focus(); },60);
}
function closeDialog(){
  $("#dialog").classList.remove("open"); $("#scrim").classList.remove("open"); D=null;
  if(lastFocus&&document.body.contains(lastFocus)) lastFocus.focus();
}
$$("[data-close]").forEach(function(b){ b.onclick=closeDialog; });
$("#scrim").onclick=function(){ if($("#confirm").classList.contains("open")) closeConfirm(); else closeDialog(); };
document.addEventListener("keydown",function(e){
  if(e.key!=="Escape") return;
  if($("#confirm").classList.contains("open")) closeConfirm(); else if(D) closeDialog();
});
$("#d-form").addEventListener("submit",function(e){
  e.preventDefault(); if(!D) return;
  $$(".field.invalid",$("#d-body")).forEach(function(f){ f.classList.remove("invalid"); });
  if(D.save($("#d-body"))===true){ var msg=D.done; closeDialog(); render(); toast(msg||"Changes saved"); }
});
function invalid(name,msg){
  var f=$('[data-field="'+name+'"]',$("#d-body")); if(!f) return false;
  f.classList.add("invalid"); if(msg) $(".err",f).textContent=msg;
  var i=$("input:not([type=checkbox]),textarea,select",f); if(i) i.focus();
  return false;
}
function field(name,label,input,hint,extra){
  return '<div class="field" data-field="'+name+'"><div class="lbl-row"><label for="f-'+name+'">'+label+'</label>'+(extra||'')+'</div>'+input+
    (hint?'<div class="hint">'+hint+'</div>':'')+'<div class="err"></div></div>';
}
function textInput(name,v,ph,type){ return '<input class="input" id="f-'+name+'" name="'+name+'" type="'+(type||"text")+'" value="'+esc(v==null?"":v)+'" placeholder="'+esc(ph||"")+'" autocomplete="off">'; }
function val(root,name){ var el=$('[name="'+name+'"]',root); return el?el.value.trim():""; }

/* ================= Data ================= */
var S = {
  departments:[
    {id:"d1",name:"Production",active:true},
    {id:"d2",name:"Quality",active:true},
    {id:"d3",name:"Admin",active:true},
    {id:"d4",name:"Authentication",active:true}
  ],
  users:[
    {id:"p1",name:"Aarti Kulkarni",email:"aarti.kulkarni@jewelex.com",dept:"d1",role:"Requester",active:true},
    {id:"p2",name:"Rakesh Shah",email:"rakesh.shah@jewelex.com",dept:"d1",role:"Approver",active:true},
    {id:"p3",name:"Neha Iyer",email:"neha.iyer@jewelex.com",dept:"d2",role:"Approver",active:true},
    {id:"p4",name:"Sameer Patel",email:"sameer.patel@jewelex.com",dept:"d2",role:"Requester",active:true},
    {id:"p5",name:"Meera Joshi",email:"meera.joshi@jewelex.com",dept:"d3",role:"Finance",active:true},
    {id:"p6",name:"Farhan Qureshi",email:"farhan.qureshi@jewelex.com",dept:"d3",role:"Admin",active:true},
    {id:"p7",name:"Kavya Nair",email:"kavya.nair@jewelex.com",dept:"d4",role:"Requester",active:false}
  ]
};
var ROLES = ["Requester","Approver","Finance","Admin"];
var ROLE_HELP = {
  Requester:"Can raise PRs for their own department and track their status.",
  Approver:"Can raise PRs and approve the ones routed to them by the approval authority setup.",
  Finance:"Receives new vendor requests, runs vendor KYC and sees all approved PRs.",
  Admin:"Can change every master in Admin Configuration, and manage users."
};
var ui = {q:{},dept:"all",role:"all"};
function dept(id){ return byId(S.departments,id); }

/* ================= View ================= */
function render(){
  $("#u-count").textContent=S.users.length;
  var ae=document.activeElement, focused=ae&&ae.getAttribute&&ae.getAttribute("data-search"), caret=focused?ae.selectionStart:0;
  var m=match(ui.q.users);
  var list=S.users.filter(function(u){
    var d=dept(u.dept);
    return m(u.name,u.email,d?d.name:"",u.role)&&(ui.dept==="all"||u.dept===ui.dept)&&(ui.role==="all"||u.role===ui.role);
  });
  var rows=list.map(function(u){
    var d=dept(u.dept);
    return '<tr class="'+(u.active?'':'inactive')+'"><td><div class="who">'+avatar(u.name)+'<div><b>'+esc(u.name)+'</b><small>'+esc(u.email)+'</small></div></div></td>'+
      '<td>'+(d?esc(d.name):'<span style="color:var(--danger)">Not set</span>')+'</td><td><span class="tag role-'+u.role+'">'+u.role+'</span></td>'+
      '<td class="status">'+sw(u.active,"toggle-user",u.id,"Active: "+u.name)+'</td><td class="actions">'+rowActions("user",u.id,u.name)+'</td></tr>';
  }).join("");
  var deptOpts='<option value="all">All departments</option>'+S.departments.map(function(d){ return '<option value="'+d.id+'"'+(ui.dept===d.id?' selected':'')+'>'+esc(d.name)+'</option>'; }).join("");
  var roleOpts='<option value="all">All roles</option>'+ROLES.map(function(r){ return '<option'+(ui.role===r?' selected':'')+'>'+r+'</option>'; }).join("");
  var empty=S.users.length?'<div class="empty"><b>No users match these filters</b>Clear the search or pick another department or role.</div>'
    :'<div class="empty"><b>No users yet</b>Add the people who will raise and approve PRs.<br><button class="btn" data-action="add-user">'+I.plus+'Add user</button></div>';
  $("#view").innerHTML='<div class="toolbar">'+searchBox("users","Search by name or email")+
    '<select class="select" data-filter="dept" aria-label="Department">'+deptOpts+'</select>'+
    '<select class="select" data-filter="role" aria-label="Role">'+roleOpts+'</select></div>'+
    '<div class="panel">'+(rows?'<div class="table-wrap"><table><thead><tr><th>User</th><th>Department</th><th>Role</th><th>Active</th><th><span class="sr">Actions</span></th></tr></thead><tbody>'+rows+'</tbody></table></div>':empty)+'</div>';
  if(focused){ var s=$('[data-search="'+focused+'"]'); if(s){ s.focus(); s.setSelectionRange(caret,caret); } }
}

/* ================= Form ================= */
function userForm(u){
  var dOpts='<option value="">Choose department</option>'+S.departments.filter(function(d){ return d.active||(u&&u.dept===d.id); }).map(function(d){
    return '<option value="'+d.id+'"'+(u&&u.dept===d.id?' selected':'')+'>'+esc(d.name)+'</option>'; }).join("");
  var rOpts=ROLES.map(function(r){ return '<option'+((u?u.role:"Requester")===r?' selected':'')+'>'+r+'</option>'; }).join("");
  openDialog({title:u?"Edit user":"Add user",sub:u?u.email:"They can sign in once added.",saveLabel:u?"Save changes":"Add user",done:u?"User updated":"User added",
    body:field("name","Full name",textInput("name",u&&u.name,"e.g. Aarti Kulkarni"))+
      field("email","Work email",textInput("email",u&&u.email,"name@jewelex.com","email"))+
      '<div class="row2">'+field("dept","Department",'<select class="input select" id="f-dept" name="dept">'+dOpts+'</select>',"Filled in automatically on their PR form. They only pick the sub-department.")+
        field("role","Role",'<select class="input select" id="f-role" name="role">'+rOpts+'</select>')+'</div>'+
      '<div class="preview info" id="role-help"></div>',
    setup:function(r){
      function paint(){ $("#role-help",r).textContent=ROLE_HELP[val(r,"role")]; }
      $('[name="role"]',r).onchange=paint; paint();
    },
    save:function(r){
      var name=val(r,"name"), email=val(r,"email").toLowerCase(), dp=val(r,"dept");
      if(!name) return invalid("name","Enter the user's name.");
      if(!emailOk(email)) return invalid("email","Enter a valid email address.");
      if(S.users.some(function(x){ return x.email.toLowerCase()===email&&(!u||x.id!==u.id); })) return invalid("email","A user with this email already exists.");
      if(!dp) return invalid("dept","Choose a department.");
      var data={name:name,email:email,dept:dp,role:val(r,"role")};
      if(u) Object.assign(u,data); else S.users.push(Object.assign({id:uid("p"),active:true},data));
      return true;
    }});
}

/* ================= Events ================= */
document.addEventListener("click",function(e){
  var b=e.target.closest("[data-action]"); if(!b||b.closest("#dialog")) return;
  var act=b.getAttribute("data-action"), id=b.getAttribute("data-id"), snap;
  switch(act){
    case "add-user": return userForm();
    case "edit-user": return userForm(byId(S.users,id));
    case "toggle-user": var t=byId(S.users,id); t.active=!t.active; return render();
    case "del-user":
      var p=byId(S.users,id);
      return confirmDel("Delete "+p.name+"?","They will no longer be able to sign in. PRs they raised or approved stay as they are.",function(){
        snap=snapshot(); S.users.splice(S.users.indexOf(p),1); render(); toast(p.name+" deleted",snap); });
  }
});
document.addEventListener("input",function(e){
  var k=e.target.getAttribute&&e.target.getAttribute("data-search"); if(k){ ui.q[k]=e.target.value; render(); }
});
document.addEventListener("change",function(e){
  var f=e.target.getAttribute&&e.target.getAttribute("data-filter"); if(f){ ui[f]=e.target.value; render(); }
});

render();

}
if (typeof appsmith !== "undefined" && appsmith.onReady) { appsmith.onReady(initUserManagement); }
else if (document.readyState === "loading") { document.addEventListener("DOMContentLoaded", initUserManagement); }
else { initUserManagement(); }
